//! The `audits` table: where the audit rows land.
//!
//! The shape is deliberately small — one row per change, the before and after
//! state of the audited row as JSON, and the user who made the change.
//!
//! | column            | meaning                                            |
//! |-------------------|----------------------------------------------------|
//! | `id`              | primary key, generated by the crate as a UUIDv7     |
//! | `created_at`      | when the change happened                            |
//! | `auditable_table` | the table of the audited row                        |
//! | `auditable_id`    | the primary key of the audited row, as text         |
//! | `action`          | `create`, `update` or `delete`                      |
//! | `before_content`  | the row before the change (`null` for creates)       |
//! | `after_content`   | the row after the change (`null` for deletes)       |
//! | `updated_by_id`   | the user who made the change (`null` when nobody did) |
//! | `ip_address`      | the client address, when the change came from a request |
//! | `url`             | the request URL, when there was a request               |
//! | `user_agent`      | the request's `User-Agent`, when it had one             |
//! | `comment`         | why a read happened (`null` for writes)                 |
//!
//! `updated_by_id` and the three request columns are nullable on purpose:
//! non-HTTP writes (background jobs, webhooks, the signup bootstrap) have no
//! session and no request behind them. They are still audited, just not
//! attributed.

use std::str::FromStr;

use sea_orm::entity::prelude::*;
use serde::{Deserialize, Serialize};

use crate::record::{AuditAction, ColumnChange};
use crate::redact::REDACTED;

/// The `audits` table.
#[derive(Clone, Debug, PartialEq, Eq, DeriveEntityModel, Serialize, Deserialize)]
#[sea_orm(table_name = "audits")]
pub struct Model {
    /// Primary key.
    #[sea_orm(primary_key, auto_increment = false)]
    pub id: Uuid,
    /// When the change happened.
    pub created_at: DateTimeWithTimeZone,
    /// The table of the audited row.
    #[sea_orm(column_type = "Text")]
    pub auditable_table: String,
    /// The primary key of the audited row, in its canonical text form.
    #[sea_orm(column_type = "Text")]
    pub auditable_id: String,
    /// `create`, `update`, `delete` or `read`.
    #[sea_orm(column_type = "Text")]
    pub action: String,
    /// The audited row before the change. `None` for creates.
    #[sea_orm(column_type = "JsonBinary", nullable)]
    pub before_content: Option<Json>,
    /// The audited row after the change. `None` for deletes.
    #[sea_orm(column_type = "JsonBinary", nullable)]
    pub after_content: Option<Json>,
    /// The user who made the change. `None` for machine-made changes.
    #[sea_orm(column_type = "Text", nullable)]
    pub updated_by_id: Option<String>,
    /// The client address of the request. `None` for machine-made changes.
    #[sea_orm(column_type = "Text", nullable)]
    pub ip_address: Option<String>,
    /// The URL of the request. `None` for machine-made changes.
    #[sea_orm(column_type = "Text", nullable)]
    pub url: Option<String>,
    /// The `User-Agent` of the request. `None` for machine-made changes.
    #[sea_orm(column_type = "Text", nullable)]
    pub user_agent: Option<String>,
    /// Why a read happened. `None` for writes, and for reads the caller
    /// did not explain.
    #[sea_orm(column_type = "Text", nullable)]
    pub comment: Option<String>,
}

impl Model {
    /// The columns this record says changed, as before and after values.
    ///
    /// For a create, every stored column is reported with no before value;
    /// for a delete, with no after value. For an update, the columns present
    /// in the stored pair are the change, which is the shape current versions
    /// write. Rows written by 0.x versions hold full snapshots instead, so
    /// a column whose value is equal on both sides is filtered out as
    /// unchanged, except a redaction marker pair: a column redacted on both
    /// sides did change, and the markers are all that was stored.
    ///
    /// # Errors
    ///
    /// Returns an error when the stored action is not `create`, `update` or
    /// `delete`: a read record has no column changes to report, and an
    /// action this version of the crate does not know cannot be diffed.
    pub fn modified(&self) -> Result<Vec<ColumnChange>, DbErr> {
        let action = AuditAction::from_str(&self.action)
            .map_err(|unknown| DbErr::Custom(format!("seaorm-auto-audit: {unknown}")))?;

        let before = self.before_content.as_ref();
        let after = self.after_content.as_ref();

        let mut changes = Vec::new();
        match action {
            AuditAction::Create => {
                if let Some(object) = after.and_then(Json::as_object) {
                    changes.extend(object.iter().map(|(column, value)| ColumnChange {
                        column: column.clone(),
                        before: None,
                        after: Some(value.clone()),
                    }));
                }
            }
            AuditAction::Delete => {
                if let Some(object) = before.and_then(Json::as_object) {
                    changes.extend(object.iter().map(|(column, value)| ColumnChange {
                        column: column.clone(),
                        before: Some(value.clone()),
                        after: None,
                    }));
                }
            }
            AuditAction::Read => {
                return Err(DbErr::Custom(
                    "seaorm-auto-audit: a read record has no changes to diff".to_owned(),
                ));
            }
            AuditAction::Update => {
                let marker = Json::String(REDACTED.to_owned());
                let mut columns: Vec<&String> = Vec::new();
                if let Some(object) = before.and_then(Json::as_object) {
                    columns.extend(object.keys());
                }
                if let Some(object) = after.and_then(Json::as_object) {
                    for column in object.keys() {
                        if !columns.contains(&column) {
                            columns.push(column);
                        }
                    }
                }
                for column in columns {
                    let before_value = before.and_then(|content| content.get(column.as_str()));
                    let after_value = after.and_then(|content| content.get(column.as_str()));
                    if before_value == after_value && before_value != Some(&marker) {
                        continue;
                    }
                    changes.push(ColumnChange {
                        column: column.clone(),
                        before: before_value.cloned(),
                        after: after_value.cloned(),
                    });
                }
            }
        }
        Ok(changes)
    }
}

/// The `audits` table has no relations of its own: `auditable_table` /
/// `auditable_id` is polymorphic, and `updated_by_id` points at whichever
/// table the host application keeps its users in.
#[derive(Copy, Clone, Debug, EnumIter, DeriveRelation)]
pub enum Relation {}

impl ActiveModelBehavior for ActiveModel {}
